      de: ['Allesfresser', 'Nachtaktive Tiere', 'Können bis zu 100 kg wiegen'],
      hu: ['Mindenevők', 'Éjszakai állatok', 'Súlyuk elérheti a 100 kg-ot'],
      ro: ['Omnivori', 'Animale nocturne', 'Pot cântări până la 100 kg'],
      en: ['Omnivores', 'Nocturnal animals', 'Can weigh up to 100 kg'],
